import{_ as t,a0 as r,w as o,s as l,ao as m,I as n,x as s,a1 as p,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"7-Zip vs WinRAR vs WinZIP： 最好的文件压缩工具对比 | LCTT x X-CMD","titleTemplate":false,"description":"7-Zip vs WinRAR vs WinZIP： 最好的文件压缩工具对比 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7-Zip vs WinRAR vs WinZIP： 最好的文件压缩工具对比 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7-Zip vs WinRAR vs WinZIP： 最好的文件压缩工具对比 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161026 7-Zip vs WinRAR vs WinZIP The Best Tool for File Compression","title":"7-Zip vs WinRAR vs WinZIP： 最好的文件压缩工具对比","tag":"201611","desc":""},"relativePath":"201611/20161026 7-Zip vs WinRAR vs WinZIP The Best Tool for File Compression.md","filePath":"[post].md"}'),d={name:"201611/20161026 7-Zip vs WinRAR vs WinZIP The Best Tool for File Compression.md"};function f(w,i,Z,h,R,W){const e=r("Link");return o(),l("div",null,[i[13]||(i[13]=m('<h1 id="_7-zip-vs-winrar-vs-winzip-最好的文件压缩工具对比" tabindex="-1">7-Zip vs WinRAR vs WinZIP： 最好的文件压缩工具对比 <a class="header-anchor" href="#_7-zip-vs-winrar-vs-winzip-最好的文件压缩工具对比" aria-label="Permalink to “7-Zip vs WinRAR vs WinZIP： 最好的文件压缩工具对比”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/best-file-compression.jpg" alt=""></p><p>在拳击界里有阿里、弗雷泽和福尔曼。在游戏机界里有任天堂、索尼和微软，在 PC 压缩软件领域里有7-Zip、WinRAR 和 WinZIP。我要发动这个软件的对决吗？也许，不管怎么说它一直是一个重要的软件。</p><p>这三个程序有同样的功能，你可以获取一堆你电脑上的文件然后打包压缩它们到一个归档，压缩它们的文件大小，直到有人决定取出它们。它们都易于使用，但是哪个做的更好？我拿它们做了一个测试来找出答案。</p><p>注意：虽然还有很多其它的压缩格式，但 Winzip、7Zip 和 WinRAR 是三个 Windows 上最流行的压缩工具。那就是为什么我们只对比这三个工具。</p><p>注意：为了测试，我压缩了一堆未压缩的视频文件，总计占用 1.3GB 的空间。我还使用最好的压缩设置来测试它们而不是默认的设置。对于每个项目，我描述了如何使这些设置。</p><h3 id="_7-zip-出了免费这一大招" tabindex="-1">7-Zip 出了免费这一大招 <a class="header-anchor" href="#_7-zip-出了免费这一大招" aria-label="Permalink to “7-Zip 出了免费这一大招”">​</a></h3><p>值得一说的是，开源的 7-Zip 是免费的，没有附加条件的这一块已经拥有优势。WinRAR 本质上是免费的，除了你必须忍受每次打开它时恼人的提示告诉你试用过期了。（你付款主要是为了摆脱这个提示。）而另一方面，WinZip 在试用期结束后会锁定你。</p><h3 id="winzip" tabindex="-1">WinZip <a class="header-anchor" href="#winzip" aria-label="Permalink to “WinZip”">​</a></h3><p>在今天的世界里，我们莫名其妙地期望的一切与软件相关的都是免费的，与我们的预期相悖，WinZip 大胆的在试用期后收费 £25.95。不过，也许是因为它比竞争对手做得更好，才让其标上这么大胆的价格标签？让我们来看看。</p><p>WinZip 有一个选项可以把文件压缩成 .zipx 格式，它生成拥有比 .zip 和其它竞争者更高的压缩比。要做到这一点，选择并右键单击要压缩文件，然后单击“WinZip - &gt;添加到压缩”文件。当 WinZip 打开后，选择“压缩类型”下的“.Zipx”，然后开始压缩。</p><p>这里是我们使用两种 WinZip 压缩方法的结果：</p><ul><li>.Zip: 855MB (34% 压缩)</li><li>.Zipx: 744MB (43% 压缩)</li></ul><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-winzip.png" alt="compression-software-compared-winzip"></p><h3 id="winrar" tabindex="-1">WinRAR <a class="header-anchor" href="#winrar" aria-label="Permalink to “WinRAR”">​</a></h3><p>WinRAR 压缩的文件是 RAR 格式（这是它自己独有的名字），也有一些技巧可以获得最大的压缩。</p><p>一旦你选择要压缩文件，右击它们，请单击“添加到压缩文件”，然后勾选“创建可靠的归档”复选框。下一步，单击“压缩方式”的下拉列表，将其更改为“最佳”。WinRAR 的还有一个叫做 RAR5 的明显增强的压缩方法，所以我测试了这一点，以及标准的压缩方法。下面是我们得到的：</p><ul><li>.rar: 780MB (40% 压缩)</li><li>.rar5: 778MB (40% 压缩)</li></ul><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-winrar.png" alt="compression-software-compared-winrar"></p><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to “7-Zip”">​</a></h3><p>它没有评估版或付费版，但是随之而来的压缩质量如何？要正确测试它，选择要压缩文件，右击它们，选择“添加到压缩文件”，然后选择7-Zip。</p><p>在新的窗口中更改压缩方法 LZMA2（如果你有一个 4 核或更强的 CPU），压缩级别设置为极端，然后压缩！这里的结果：</p><ul><li>.7z: 758MB (42% 压缩)</li></ul><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-7zip.png" alt="compression-software-compared-7zip"></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>基于以上结果，我将继续坚持使用 7-zip。和技术上的“赢家” WinZip 比，这 1% 差别的压缩水平不足以为此花钱。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/10/compression-software-compared-windows.png" alt="compression-software-compared-windows"></p><p>或许你并不想下载任何第三方软件，在这种情况下，你可以使用 Windows 的内置压缩工具。要使用它，只需右键单击任何你想压缩的文件，选择“发送到”，然后“压缩文件夹”。它只把文件压缩到 892 MB的水平（31％），但它更便捷快速，而且是免费和内置的，所以我们还有抱怨吗？</p><hr>',29)),n("p",null,[i[1]||(i[1]=s("via: ",-1)),p(e,{href:"https://www.maketecheasier.com/7-zip-vs-winrar-vs-winzip/"},{default:a(()=>[...i[0]||(i[0]=[s("https://www.maketecheasier.com/7-zip-vs-winrar-vs-winzip/",-1)])]),_:1})]),n("p",null,[i[5]||(i[5]=s("作者：",-1)),p(e,{href:"https://www.maketecheasier.com/author/robzak/"},{default:a(()=>[...i[2]||(i[2]=[s("Robert Zak",-1)])]),_:1}),i[6]||(i[6]=s(" 译者：",-1)),p(e,{href:"https://github.com/wyangsun"},{default:a(()=>[...i[3]||(i[3]=[s("wyangsun",-1)])]),_:1}),i[7]||(i[7]=s(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[4]||(i[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[10]||(i[10]=s("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[8]||(i[8]=[s("LCTT",-1)])]),_:1}),i[11]||(i[11]=s(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:a(()=>[...i[9]||(i[9]=[s("Linux中国",-1)])]),_:1}),i[12]||(i[12]=s(" 荣誉推出",-1))])])}const c=t(d,[["render",f]]);export{T as __pageData,c as default};
